            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var po = this.POS[a.pos1];
            var rf = this.REFORMA[a.reforma1];
            var pl = this.PLANT[a.plant2];
            var de = this.DEPT[a.dept2];
            var ve = this.VERANO[a.verano3];
            var rp = this.REP[a.rep3];
            var te = this.TEMP[a.temp4];
            var en = this.ENER[a.energia4];
            var rep = this._clamp(c.REP0 + po[3] + rf[2] + pl[1] + de[1] + ve[2] + rp[1] + te[4] + en[2], 0.0, 10.0);
            var newh = 1.0;
            if (k >= 2) { newh = 1.0 - (1.0 - c.NEWHOTEL) * (1.0 - po[4]); }
            var adr = c.ADR0 * po[0] * (1.0 + rf[1] * po[2]);
            var avail = c.ROOMS * c.DAYS;
            var dem = c.D0 * Math.pow(po[0], -c.EL) * po[1] * de[2] * newh
                * (1.0 + c.REP_EL * (rep - c.REP0) / c.REP0);
            var pavail = c.ROOMS * c.PEAK_DAYS;
            var oavail = avail - pavail;
            var pcap = pavail * Math.min(c.MAXOCC, pl[3] * ve[0]);
            var ocap = oavail * Math.min(c.MAXOCC, pl[3]);
            var pdem = dem * c.PEAK;
            var odem = dem - pdem;
            var cap = pcap + ocap;
            var sold = Math.min(pdem, pcap) + Math.min(odem, ocap);
            var xsold = (te[1] > 0) ? te[1] * (1.0 + c.REP_EL * (rep - c.REP0) / c.REP0) : te[1];
            var xadr = adr * te[2];
            var roomsRev = sold * adr + xsold * xadr;
            var nights = sold + xsold;
            var fbRev = nights * (c.FB + de[3]);
            var rev = roomsRev + fbRev + rf[3];
            var availT = avail + te[0];
            var occ = nights / availT;
            var revpar = roomsRev / availT;
            var staff = c.STAFF * pl[0] + pl[2];
            var vr = nights * c.VAR;
            var fbc = fbRev * c.FB_COST;
            var com = roomsRev * c.OTA_SHARE * c.OTA_COM;
            var eup = (k >= 4 && en[3] === 0.0) ? c.EN_UP : 1.0;
            var energy = c.ENERGY * en[1] * (0.75 + 0.25 * eup) + en[0];
            var undist = c.UNDIST + de[0] - de[4] + ve[1] + rp[0] + te[3];
            var gop = rev - staff - vr - fbc - com - energy - undist;
            var profit = gop - c.OWN - rf[0];
            var margin = gop / rev;
            var hard = 0;
            this.HARD.forEach(function(h) { if (a[h[0]] === h[1] && k >= self.ROUND_OF[h[0]]) { hard += 1; } });
            return { k: k, a: a, gop: gop, profit: profit, margin: margin, rep: rep, occ: occ, revpar: revpar,
                     rev: rev, roomsRev: roomsRev, fbRev: fbRev, nights: nights, xsold: xsold, avail: availT,
                     staff: staff, energy: energy, undist: undist, reform: rf[0], hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.profit - c.B_LO) / (c.B_HI - c.B_LO), 0, 1),
                    this._clamp((r.revpar - c.R_LO) / (c.R_HI - c.R_LO), 0, 1),
                    this._clamp((r.rep - c.P_LO) / (c.P_HI - c.P_LO), 0, 1),
                    this._clamp((r.margin - c.G_LO) / (c.G_HI - c.G_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_B, c.W_R, c.W_P, c.W_G];
            var tw = 0, num = 0, i;
            for (i = 0; i < 4; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = this._r2(n);
            var neg = v < 0;
            var cents = Math.round(Math.abs(v) * 100);
            var whole = Math.floor(cents / 100);
            var dec = cents - whole * 100;
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + (dec < 10 ? '0' : '') + String(dec);
            return (neg && cents > 0 ? '-' : '') + s;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtRep(n) {
            return this._fmtDec2(n) + ' / 10';
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _fmtMoney2(n) {
            var body = this._fmtDec2(Math.abs(n));
            var neg = this._r2(n) < 0;
            if (this._lang() === 'en') { return (neg ? '-' : '') + '€' + body; }
            return (neg ? '-' : '') + body + ' €';
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var mH = ds.profitHistory || [];
            var vH = ds.revparHistory || [];
            var rH = ds.repHistory || [];
            var fH = ds.gopmHistory || [];
            var tH = ds.occHistory || [];
            var n = mH.length;
            this._set('profitDisplay', n ? this._fmtMoney(mH[n - 1]) : '-');
            this._set('revparDisplay', n ? this._fmtMoney2(vH[n - 1]) : '-');
            this._set('repDisplay', n ? this._fmtRep(rH[n - 1]) : '-');
            this._set('gopmDisplay', n ? this._fmtPct1(fH[n - 1]) : '-');
            this._set('occDisplay', n ? this._fmtPct1(tH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { pos1: 'po', reforma1: 'rf', plant2: 'pl', dept2: 'de', verano3: 've', rep3: 'rp', temp4: 'te', energia4: 'en' };
            var opts = {
                pos1: ['segmento', 'subir', 'igual', 'bajar'],
                reforma1: ['habitaciones', 'spa', 'nada', 'integral'],
                plant2: ['fijodisc', 'ett', 'minima', 'externa'],
                dept2: ['mant', 'fyb', 'igual', 'recorte'],
                verano3: ['llamar', 'extras', 'nada', 'negro'],
                rep3: ['responder', 'plantilla', 'ignorar', 'agencia'],
                temp4: ['senior', 'cerrar', 'adelantar', 'abrir'],
                energia4: ['eficiencia', 'fijo', 'nada', 'cortar']
            };
            var keys = {
                fb_po_segmento: 1, fb_po_subir: 1, fb_po_igual: 1, fb_po_bajar: 1,
                fb_rf_habitaciones: 1, fb_rf_spa: 1, fb_rf_nada: 1, fb_rf_integral: 1,
                fb_pl_fijodisc: 1, fb_pl_ett: 1, fb_pl_minima: 1, fb_pl_externa: 1,
                fb_de_mant: 1, fb_de_fyb: 1, fb_de_igual: 1, fb_de_recorte: 1,
                fb_ve_llamar: 1, fb_ve_extras: 1, fb_ve_nada: 1, fb_ve_negro: 1,
                fb_rp_responder: 1, fb_rp_plantilla: 1, fb_rp_ignorar: 1, fb_rp_agencia: 1,
                fb_te_senior: 1, fb_te_cerrar: 1, fb_te_adelantar: 1, fb_te_abrir: 1,
                fb_en_eficiencia: 1, fb_en_fijo: 1, fb_en_nada: 1, fb_en_cortar: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

