            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Season profit', data: [], borderColor: '#1f5f7a', backgroundColor: 'rgba(31,95,122,0.12)', borderWidth: 2 },
                            { label: 'GOP', data: [], borderColor: '#9a5b13', backgroundColor: 'rgba(154,91,19,0.10)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#1f5f7a', backgroundColor: 'rgba(31,95,122,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
