        getHistoryTableConfig() {
            var self = this;
            var money = function(v) { return self._fmtMoney(v); };
            var pct = function(v) { return self._fmtPct1(v); };
            var money2 = function(v) { return self._fmtMoney2(v); };
            var rating = function(v) { return self._fmtDec2(v); };
            return [
                { key: 'results.profit', label: 'Season profit', i18nKey: 'col_profit', formatter: money },
                { key: 'results.revpar', label: 'RevPAR', i18nKey: 'col_revpar', formatter: money2 },
                { key: 'results.rep', label: 'Online reputation', i18nKey: 'col_rep', formatter: rating },
                { key: 'results.gopm', label: 'GOP margin', i18nKey: 'col_gopm', formatter: pct },
                { key: 'results.occ', label: 'Occupancy', i18nKey: 'col_occ', formatter: pct },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
