        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                profit: kp.profit,
                revpar: kp.revpar,
                rep: kp.rep,
                gopm: kp.gopm,
                occ: kp.occ,
                gop: kp.gop,
                rev: Math.round(m.rev),
                nights: Math.round(m.nights),
                xsold: Math.round(m.xsold),
                energy: Math.round(m.energy),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2711-cm">'
                + '<div class="ej2711-cm-score">' + score + '<span class="ej2711-cm-max">/100</span></div>'
                + '<div class="ej2711-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2711-cm-kpis">'
                + '<div class="ej2711-cm-kpi">' + this._t('cm_kpi_profit') + ' <strong>' + this._fmtMoney(s.profit || 0) + '</strong></div>'
                + '<div class="ej2711-cm-kpi">' + this._t('cm_kpi_revpar') + ' <strong>' + this._fmtMoney2(s.revpar || 0) + '</strong></div>'
                + '<div class="ej2711-cm-kpi">' + this._t('cm_kpi_rep') + ' <strong>' + this._fmtRep(s.rep || 0) + '</strong></div>'
                + '<div class="ej2711-cm-kpi">' + this._t('cm_kpi_gopm') + ' <strong>' + this._fmtPct1(s.gopm || 0) + '</strong></div>'
                + '<div class="ej2711-cm-kpi">' + this._t('cm_kpi_occ') + ' <strong>' + this._fmtPct1(s.occ || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2711-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2711-cm-insights">' + items + '</ul>'
                + '</div>';
        }

